def cumulative_value_counts(data, columns):
    result = {}
    if not data:
        for col in columns:
            result[col] = {}
        return result
    all_values = set()
    for row in data:
        for v in row:
            all_values.add(v)
    distinct = sorted(all_values)
    for idx, col in enumerate(columns):
        col_vals = sorted(row[idx] for row in data if idx < len(row))
        result[col] = {v: bisect_right(col_vals, v) for v in distinct}
    return result

