def word_length_summary(words, letter):
    if not words:
        return None
    letter = str(letter).lower()
    lengths = sorted(
        len(w) for w in words
        if isinstance(w, str) and w and w[0].lower() == letter
    )
    if not lengths:
        return None

    n = len(lengths)

    def quantile(p):
        pos = (n - 1) * p
        lo = int(pos)
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return float(lengths[lo] + (lengths[hi] - lengths[lo]) * frac)

    return {
        'min': float(lengths[0]),
        'q1': quantile(0.25),
        'median': quantile(0.5),
        'q3': quantile(0.75),
        'max': float(lengths[-1]),
    }

