def correlation_with_fit_line(a, b):
    a = [float(x) for x in a]
    b = [float(y) for y in b]
    n = len(a)
    if n != len(b):
        raise ValueError("Input lists must have equal length")
    if n < 2:
        raise ValueError("At least two data points are required")
    mean_a = math.fsum(a) / n
    mean_b = math.fsum(b) / n
    da = [x - mean_a for x in a]
    db = [y - mean_b for y in b]
    sxy = math.fsum(x * y for x, y in zip(da, db))
    sxx = math.fsum(x * x for x in da)
    syy = math.fsum(y * y for y in db)
    if sxx == 0:
        raise ValueError("Variance of a is zero; regression undefined")
    slope = sxy / sxx
    intercept = mean_b - slope * mean_a
    if syy == 0:
        r = float('nan')
    else:
        r = sxy / math.sqrt(sxx * syy)
