def date_histogram(dates, date_format, bins):
    if isinstance(bins, bool) or not isinstance(bins, int) or bins < 1:
        raise ValueError("bins must be a positive integer")
    parsed = []
    for d in dates:
        try:
            parsed.append(datetime.strptime(d, date_format))
        except (ValueError, TypeError) as e:
            raise ValueError("date %r does not match format %r" % (d, date_format)) from e
    counts = [0] * bins
    if not parsed:
        return counts
    lo = min(parsed)
    hi = max(parsed)

    def to_us(td):
        return (td.days * 86400 + td.seconds) * 1000000 + td.microseconds

    total = to_us(hi - lo)
    if total == 0:
        # Mimic numpy: range expanded to [x - 0.5, x + 0.5]; value sits at the centre
        idx = min(bins // 2, bins - 1)
        counts[idx] += len(parsed)
        return counts
    for p in parsed:
        off = to_us(p - lo)
        idx = (off * bins) // total
        if idx >= bins:
            idx = bins - 1
        counts[idx] += 1
    return counts

