import math
from fractions import Fraction


def skewness_and_kurtosis(sample):
    data = list(sample)
    n = len(data)
    if n == 0:
        raise ValueError("sample must contain at least one value")
    for x in data:
        if isinstance(x, float) and not math.isfinite(x):
            return (float('nan'), float('nan'))
    fr = [Fraction(x) for x in data]
    mean = sum(fr) / n
    devs = [x - mean for x in fr]
    m2 = sum(d * d for d in devs) / n
    if m2 == 0:
        return (float('nan'), float('nan'))
    m3 = sum(d * d * d for d in devs) / n
    m4 = sum((d * d) * (d * d) for d in devs) / n
    skew = float(m3) / (float(m2) ** 1.5)
    kurt = float(m4 / (m2 * m2) - 3)
    return (skew, kurt)
